python3 << 'EOF'
import re

years = [1978, 1979, 1980, 1981, 1982]

data = {}

for year in years:
    filepath = f'/app/resources/treasury_bulletin_{year}_05.txt'
    with open(filepath, 'r') as f:
        content = f.read()

    result = {'bills': None, 'notes': None, 'bonds': None}

    for line in content.split('\n'):
        lower = line.lower().strip()
        if lower.startswith('| total treasury'):
            parts = [p.strip() for p in line.split('|') if p.strip()]
            sec_type = parts[0].replace('total treasury ', '').strip()

            # Find the commercial banks column - it's the 4th element (index 3)
            if len(parts) >= 4:
                cb_value = parts[3]
                # Clean up the value (remove .0 or convert)
                try:
                    cb_value = int(float(cb_value))
                except:
                    cb_value = None

                if 'bills' in sec_type:
                    result['bills'] = cb_value
                elif 'notes' in sec_type:
                    result['notes'] = cb_value
                elif 'bonds' in sec_type:
                    result['bonds'] = cb_value

    data[year] = result

    print(f"{year}:")
    print(f"  Bills: {result['bills']}")
    print(f"  Notes: {result['notes']}")
    print(f"  Bonds: {result['bonds']}")

# Now compute total marketables = bills + notes + bonds (marketable securities)
print("\n\nTotal marketable interest-bearing securities held by commercial banks:")
for year in years:
    d = data[year]
    total = (d['bills'] or 0) + (d['notes'] or 0) + (d['bonds'] or 0)
    print(f"{year}: {total}")
EOF
